class SearchByPolygonRequest(BaseModel):
    """
    Map-bounded property search. `viewport_polygon` is an ordered ring of points with
    explicit `lat` and `lng` (WGS-84 decimal degrees), closing implicitly by edge order.
    Omit `viewport_polygon` for read-only `onlyCached` requests (hydrate persisted results).
    For `forceSearch`, include `viewport_polygon` for map-bounded search or rely on server isochrone from preferences when omitted.
    Optional filters come from `user_preferences` and strictness flags; results are
    scored server-side unless overridden by route-specific sort parameters.

    """

    viewport_polygon: list[ViewportPolygonPoint] | None = Field(
        None,
        description="Closed polygon covering the visible map region (typically 4+ corners).\nOptional when `onlyCached` is true (no new search); recommended when driving `forceSearch` from the map.\n",
    )
    user_preferences: UserPreferencesData | None = Field(
        None,
        description="Buyer preference slice applied as soft or hard filters depending on `preferences_strict_filter`.",
    )
    preferences_strict_filter: bool | None = Field(
        None,
        description="When true, exclude properties that fail preference constraints instead of only down-ranking them.",
    )
    perBucketPages: int | None = Field(
        None,
        description="Cap on hits per internal price or geography bucket when paginating large result sets.",
    )
    forceSearch: bool | None = Field(
        None,
        description="Bypass short-circuit caches and recompute matches (admin or debug style refresh).",
    )
    onlyCached: bool | None = Field(
        None,
        description="When true, return previously materialized results only without hitting upstream MLS.",
    )
    hydrateListings: bool | None = Field(
        None,
        description="When true with `onlyCached`, refresh listing snapshots (price, status, beds, etc.) from Slipstream\nusing each persisted home_id before responding. Does not re-run search or change match scores.\n",
    )
    preferences_user_id: str | None = Field(
        None,
        description="Optional subject for preference scoring (agents: must be a linked client id; buyers are always scoped to self).\nResolved server-side via `resolve_preferences_user_id_for_research`.\n",
    )


