class Agreement(BaseModel):
    """
    DocuSign-backed agreement between an agent and buyer, including envelope metadata,
    participant list, optional revisions/history, and denormalized names for list views.
    `docusign_envelope_id` is the primary correlation key with DocuSign.

    """

    id: str
    agent_id: str
    buyer_id: str
    title: str
    agreement_type: AgreementType
    status: AgreementStatus
    property_address: str | None = Field(
        None, description="Human-readable property line for titles and notifications."
    )
    description: str | None = Field(
        None,
        description="Free-text summary or internal notes shown on agreement detail.",
    )
    docusign_envelope_id: str | None = Field(
        None,
        description="Current DocuSign envelope UUID used for API callbacks and deep links.",
    )
    docusign_source_template_id: str | None = Field(
        None,
        description="When set, envelope is created from this DocuSign template instead of PDF revisions.",
    )
    docusign_status: str | None = Field(
        None,
        description="Last observed DocuSign composite status string (e.g. sent, completed).",
    )
    created_at: AwareDatetime
    updated_at: AwareDatetime
    sent_at: AwareDatetime | None = None
    completed_at: AwareDatetime | None = None
    voided_at: AwareDatetime | None = None
    current_revision_id: str | None = None
    signed_document_path: str | None = Field(
        None, description="Storage path to the merged signed PDF after completion."
    )
    certificate_path: str | None = Field(
        None, description="Optional path to the completion certificate artifact."
    )
    participants: list[AgreementParticipant] | None = None
    revisions: list[AgreementRevision] | None = None
    events: list[AgreementEvent] | None = None
    current_revision: AgreementRevision | None = None
    agent_name: str | None = None
    buyer_name: str | None = None
    buyer_email: EmailStr | None = None


